import { mkdir, readFile, writeFile } from 'node:fs/promises';

const root = new URL('../', import.meta.url);
const moneyLayoutCss = await readFile(new URL('src/ui/money-layout.css', root), 'utf8');
const moneyLayoutClient = await readFile(new URL('src/ui/money-layout.js', root), 'utf8');
await mkdir(new URL('.build/', root), { recursive: true });
await writeFile(new URL('.build/money-layout-assets.mjs', root),
  '// Generated by npm run build from editable UI files.\n' +
  `export const moneyLayoutCss = ${JSON.stringify(moneyLayoutCss)};\n` +
  `export const moneyLayoutClient = ${JSON.stringify(moneyLayoutClient)};\n`);
console.log('Money layout overlay assembled; original frontend assets are still required.');
